internal/email/doc.go:10918:// Package email provides SMTP email sending functionality for self-hosted Memos instances.
internal/email/doc.go:10919://
internal/email/doc.go:10920:// This package is designed for self-hosted environments where instance administrators
internal/email/doc.go:10921:// configure their own SMTP servers. It follows industry-standard patterns used by
internal/email/doc.go:10922:// platforms like GitHub, GitLab, and Discourse.
internal/email/doc.go:10923://
internal/email/doc.go:10924:// # Configuration
internal/email/doc.go:10925://
internal/email/doc.go:10926:// The package requires SMTP server configuration provided by the instance administrator:
internal/email/doc.go:10927://
internal/email/doc.go:10928://	config := &email.Config{
internal/email/doc.go:10929://	    SMTPHost:     "smtp.gmail.com",
internal/email/doc.go:10930://	    SMTPPort:     587,
internal/email/doc.go:10931://	    SMTPUsername: "your-email@gmail.com",
internal/email/doc.go:10932://	    SMTPPassword: "your-app-password",
internal/email/doc.go:10933://	    FromEmail:    "noreply@yourdomain.com",
internal/email/doc.go:10934://	    FromName:     "Memos Notifications",
internal/email/doc.go:10935://	    UseTLS:       true,
internal/email/doc.go:10936://	}
internal/email/doc.go:10937://
internal/email/doc.go:10938:// # Common SMTP Settings
internal/email/doc.go:10939://
internal/email/doc.go:10940:// Gmail (requires App Password):
internal/email/doc.go:10941://   - Host: smtp.gmail.com
internal/email/doc.go:10942://   - Port: 587 (TLS) or 465 (SSL)
internal/email/doc.go:10943://   - Username: your-email@gmail.com
internal/email/doc.go:10944://   - UseTLS: true (for port 587) or UseSSL: true (for port 465)
internal/email/doc.go:10945://
internal/email/doc.go:10946:// SendGrid:
internal/email/doc.go:10947://   - Host: smtp.sendgrid.net
internal/email/doc.go:10948://   - Port: 587
internal/email/doc.go:10949://   - Username: apikey
internal/email/doc.go:10950://   - Password: your-sendgrid-api-key
internal/email/doc.go:10951://   - UseTLS: true
internal/email/doc.go:10952://
internal/email/doc.go:10953:// AWS SES:
internal/email/doc.go:10954://   - Host: email-smtp.[region].amazonaws.com
internal/email/doc.go:10955://   - Port: 587
internal/email/doc.go:10956://   - Username: your-smtp-username
internal/email/doc.go:10957://   - Password: your-smtp-password
internal/email/doc.go:10958://   - UseTLS: true
internal/email/doc.go:10959://
internal/email/doc.go:10960:// Mailgun:
internal/email/doc.go:10961://   - Host: smtp.mailgun.org
internal/email/doc.go:10962://   - Port: 587
internal/email/doc.go:10963://   - Username: your-mailgun-smtp-username
internal/email/doc.go:10964://   - Password: your-mailgun-smtp-password
internal/email/doc.go:10965://   - UseTLS: true
internal/email/doc.go:10966://
internal/email/doc.go:10967:// # Sending Email
internal/email/doc.go:10968://
internal/email/doc.go:10969:// Synchronous (waits for completion):
internal/email/doc.go:10970://
internal/email/doc.go:10971://	message := &email.Message{
internal/email/doc.go:10972://	    To:      []string{"user@example.com"},
internal/email/doc.go:10973://	    Subject: "Welcome to Memos",
internal/email/doc.go:10974://	    Body:    "Thank you for joining!",
internal/email/doc.go:10975://	    IsHTML:  false,
internal/email/doc.go:10976://	}
internal/email/doc.go:10977://
internal/email/doc.go:10978://	err := email.Send(config, message)
internal/email/doc.go:10979://	if err != nil {
internal/email/doc.go:10980://	    // Handle error
internal/email/doc.go:10981://	}
internal/email/doc.go:10982://
internal/email/doc.go:10983:// Asynchronous (returns immediately):
internal/email/doc.go:10984://
internal/email/doc.go:10985://	email.SendAsync(config, message)
internal/email/doc.go:10986://	// Errors are logged but not returned
internal/email/doc.go:10987://
internal/email/doc.go:10988:// # HTML Email
internal/email/doc.go:10989://
internal/email/doc.go:10990://	message := &email.Message{
internal/email/doc.go:10991://	    To:      []string{"user@example.com"},
internal/email/doc.go:10992://	    Subject: "Welcome!",
internal/email/doc.go:10993://	    Body:    "<html><body><h1>Welcome to Memos!</h1></body></html>",
internal/email/doc.go:10994://	    IsHTML:  true,
internal/email/doc.go:10995://	}
internal/email/doc.go:10996://
internal/email/doc.go:10997:// # Security Considerations
internal/email/doc.go:10998://
internal/email/doc.go:10999://   - Always use TLS (port 587) or SSL (port 465) for production
internal/email/doc.go:11000://   - Store SMTP credentials securely (environment variables or secrets management)
internal/email/doc.go:11001://   - Use app-specific passwords for services like Gmail
internal/email/doc.go:11002://   - Validate and sanitize email content to prevent injection attacks
internal/email/doc.go:11003://   - Rate limit email sending to prevent abuse
internal/email/doc.go:11004://
internal/email/doc.go:11005:// # Error Handling
internal/email/doc.go:11006://
internal/email/doc.go:11007:// The package returns descriptive errors for common issues:
internal/email/doc.go:11008://   - Configuration validation errors (missing host, invalid port, etc.)
internal/email/doc.go:11009://   - Message validation errors (missing recipients, subject, or body)
internal/email/doc.go:11010://   - Connection errors (cannot reach SMTP server)
internal/email/doc.go:11011://   - Authentication errors (invalid credentials)
internal/email/doc.go:11012://   - SMTP protocol errors (recipient rejected, etc.)
internal/email/doc.go:11013://
internal/email/doc.go:11014:// All errors are wrapped with context using github.com/pkg/errors for better debugging.
